window.docContents[30].resolve({"/Planned-constructions/UD-V/#Core-C_________-natural-semantics--Planned-constructions--UD-V":{"contents":"An object is a record of locations with a class tag. The new allocates the locations of the fields and calls the constructor. Vectors are objects like any other.\n\nA method call binds this to the location of the object. With virtual, the method is chosen by the class tag of the object, not by the static type of the pointer.\n\nThe delete p runs the destructor with this at the location of the object and removes the locations of the object from . Double delete, access after delete and delete through a base pointer without a virtual destructor are error.\n\nA pointer to a derived class is accepted where a pointer to the base is expected. It is the only implicit conversion between classes.\n\n","context":"Core C++, natural semantics\u0009Planned constructions","header":"5.3. UD V","id":"/Planned-constructions/UD-V/#Core-C_________-natural-semantics--Planned-constructions--UD-V"}});